export default function Home() {
    const [filter, setFilter] = useState("all");
    const [statusFilter, setStatusFilter] = useState("all");

    const filteredIndicators = allIndicators.filter(ind => {
        const matchesOE = filter === "all" || ind.oe === filter;
        const matchesStatus = statusFilter === "all" || ind.status === statusFilter;
        return matchesOE && matchesStatus;
    });

    const getStatusBadge = (status: string) => {
        switch (status) {
            case "Verde": return <Badge className="bg-emerald-500 hover:bg-emerald-600 border-none shrink-0 shadow-sm text-[10px] uppercase">Conforme</Badge>;
            case "Amarelo": return <Badge className="bg-amber-500 hover:bg-amber-600 border-none shrink-0 text-zinc-900 text-[10px] uppercase">Atenção</Badge>;
            case "Vermelho": return <Badge className="bg-red-600 hover:bg-red-700 border-none shrink-0 shadow-sm text-[10px] uppercase">Crítico</Badge>;
            default: return <Badge className="bg-slate-500 border-none shrink-0 text-[10px] uppercase">N/A</Badge>;
        }
    };

    const getStatusBorder = (status: string) => {
        switch (status) {
            case "Verde": return "border-l-4 border-l-emerald-500";
            case "Amarelo": return "border-l-4 border-l-amber-500";
            case "Vermelho": return "border-l-4 border-l-red-600";
            default: return "";
        }
    };

    return (
        <div className="flex min-h-screen flex-col bg-slate-50 dark:bg-zinc-950 font-sans">
            {/* Header Fênix */}
            <header className="border-b bg-white/80 backdrop-blur-md px-8 py-3 dark:bg-zinc-900/80 flex justify-between items-center shadow-sm sticky top-0 z-50">
                <div className="flex items-center gap-3">
                    <div className="h-8 w-1 bg-red-700 rounded-full" />
                    <h1 className="text-lg font-black tracking-tighter text-slate-900 dark:text-white uppercase">
                        CBMAL <span className="font-light text-slate-500 lowercase tracking-normal italic ml-1">Painel Tático v2.2</span>
                    </h1>
                </div>

                <div className="flex items-center gap-4">
                    <Select onValueChange={setStatusFilter} defaultValue="all">
                        <SelectTrigger className="w-[180px] h-9 bg-slate-100 dark:bg-zinc-800 border-none font-semibold text-xs">
                            <SelectValue placeholder="Status do Farol" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="all" className="text-xs font-bold text-slate-500">Todos os Status</SelectItem>
                            <SelectItem value="Verde" className="text-xs font-bold text-emerald-600">🟢 Conforme</SelectItem>
                            <SelectItem value="Amarelo" className="text-xs font-bold text-amber-500">🟡 Atenção</SelectItem>
                            <SelectItem value="Vermelho" className="text-xs font-bold text-red-600">🔴 Crítico</SelectItem>
                        </SelectContent>
                    </Select>

                    <Select onValueChange={setFilter} defaultValue="all">
                        <SelectTrigger className="w-[280px] h-9 bg-slate-100 dark:bg-zinc-800 border-none font-semibold text-xs">
                            <SelectValue placeholder="Filtrar por Objetivo" />
                        </SelectTrigger>
                        <SelectContent>
                            {OEs.map(oe => (
                                <SelectItem key={oe.id} value={oe.id} className="text-xs">{oe.name}</SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                    <Button className="bg-red-700 hover:bg-red-800 text-white h-9 px-4 text-xs font-bold uppercase transition-all shadow-md" size="sm">
                        Relatório APO
                    </Button>
                </div>
            </header>

            <main className="flex-1 p-6 space-y-6 max-w-[1400px] mx-auto w-full">
                {/* Sumário de Carga */}
                <div className="flex items-center justify-between border-b pb-4">
                    <div className="space-y-1">
                        <h2 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">Visão Corrente</h2>
                        <p className="text-xs text-slate-500 font-medium italic">Dados extraídos do Caderno de Indicadores Estratégicos v2.2</p>
                    </div>
                    <div className="flex gap-8">
                        <div className="flex flex-col items-end">
                            <span className="text-2xl font-black text-slate-800 dark:text-white tracking-tighter">{filteredIndicators.length}</span>
                            <span className="text-[10px] text-slate-400 font-bold uppercase">Indicadores Exibidos</span>
                        </div>
                    </div>
                </div>

                {/* Dashboard Grid 4x4 */}
                <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                    {filteredIndicators.map((ind) => (
                        <Card key={ind.id} className={`group hover:shadow-xl transition-all duration-300 bg-white dark:bg-zinc-900 flex flex-col ${getStatusBorder(ind.status)}`}>
                            <CardHeader className="p-4 space-y-3">
                                <div className="flex flex-col items-start text-left gap-2 relative">
                                    <div className="absolute right-0 top-0">
                                        {getStatusBadge(ind.status)}
                                    </div>

                                    <div className="space-y-1 w-full mt-6">
                                        <div className="flex items-center gap-2">
                                            <span className="text-[10px] font-bold text-red-700 dark:text-red-500 uppercase tracking-widest">{ind.oe}</span>
                                            <span className="text-[10px] font-medium text-slate-400">|</span>
                                            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{ind.id}</span>
                                        </div>
                                        <CardTitle className="text-sm font-bold leading-snug text-slate-800 dark:text-slate-100 uppercase group-hover:text-red-700 transition-colors pt-1">
                                            {ind.name}
                                        </CardTitle>
                                    </div>
                                </div>
                            </CardHeader>
                            <CardContent className="p-4 pt-0 mt-auto">
                                <div className="mb-4 flex items-center gap-2">
                                    <div className="h-4 w-0.5 bg-slate-200 dark:bg-zinc-700" />
                                    <span className="text-[11px] font-semibold text-slate-500 uppercase">{ind.sector}</span>
                                </div>

                                <div className="grid grid-cols-2 gap-4 border-t pt-4 border-slate-100 dark:border-zinc-800">
                                    <div className="space-y-0.5">
                                        <span className="text-[10px] font-semibold text-slate-400 uppercase">Realizado</span>
                                        <div className="text-xl font-bold text-slate-900 dark:text-white">{ind.current}</div>
                                    </div>
                                    <div className="space-y-0.5 text-right">
                                        <span className="text-[10px] font-semibold text-slate-400 uppercase">Meta Pactuada</span>
                                        <div className="text-sm font-medium text-slate-500">{ind.target}</div>
                                    </div>
                                </div>

                                {/* Visualização de Progresso Mockup (Simbólica) */}
                                <div className="mt-4 space-y-1">
                                    <div className="flex justify-between text-[10px] font-semibold text-slate-400">
                                        <span>Nível de Entrega</span>
                                        <span>{ind.status === 'Verde' ? '100' : ind.status === 'Amarelo' ? '80' : '45'}%</span>
                                    </div>
                                    <Progress
                                        value={ind.status === 'Verde' ? 100 : ind.status === 'Amarelo' ? 80 : 45}
                                        indicatorClassName={ind.status === 'Verde' ? 'bg-emerald-500' : ind.status === 'Amarelo' ? 'bg-amber-500' : 'bg-red-600'}
                                    />
                                </div>
                            </CardContent>
                        </Card>
                    ))}
                </div>

                {filteredIndicators.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-300">
                        <div className="text-4xl">🔍</div>
                        <p className="mt-4 text-sm font-bold uppercase tracking-widest">Nenhum dado encontrado para este filtro</p>
                    </div>
                )}
            </main>

            {/* Footer APO */}
            <footer className="py-8 border-t px-8 text-center text-[9px] text-slate-400 uppercase tracking-[0.3em] bg-white dark:bg-zinc-950">
                Assessoria de Planejamento e Orçamento | Estado-Major Geral CBMAL
            </footer>
        </div>
    );
}
